-- D-27: characters and gear are authored in STR / INT / VIT / AGI (docs/combat/STAT_MATH.md).
-- The derived-stat columns of `characters` are renamed in place (their CHECKs carry over), the attribute columns are added, and the
-- seeded characters, gear definitions, set bonuses and weapon role stats are rewritten once from tools/lib/balance.ts. Published
-- catalogs are frozen JSON and keep their legacy stats; the seeds stay INSERT OR IGNORE, so Control Center edits made after this survive.
ALTER TABLE characters RENAME COLUMN base_hp TO base_vit;
ALTER TABLE characters RENAME COLUMN base_atk TO base_str;
ALTER TABLE characters RENAME COLUMN base_def TO base_int;
ALTER TABLE characters RENAME COLUMN base_spd TO base_agi;
ALTER TABLE characters RENAME COLUMN growth_hp TO growth_vit;
ALTER TABLE characters RENAME COLUMN growth_atk TO growth_str;
ALTER TABLE characters RENAME COLUMN growth_def TO growth_int;
ALTER TABLE characters RENAME COLUMN growth_spd TO growth_agi;
ALTER TABLE characters ADD COLUMN power_stat TEXT NOT NULL DEFAULT 'str' CHECK (power_stat IN ('str', 'int'));
ALTER TABLE characters ADD COLUMN armor INTEGER NOT NULL DEFAULT 0 CHECK (armor BETWEEN 0 AND 100);
UPDATE characters SET power_stat = 'str', base_str = 3, base_int = 1, base_vit = 5, base_agi = 2, growth_str = 0.3, growth_int = 0.1, growth_vit = 0.5, growth_agi = 0.15, armor = 1 WHERE id = 'mahmut';
